def _write_resource(out, v, depth):
    _closed_enum(Verification, v.verification)
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "handle")
    out += b": "
    _esc(out, v.handle)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "digest")
    out += b": "
    _esc(out, v.digest)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
