class ContentChanges:
    """Bounded authorized observation of objects a content store gains or loses.
    The provider journal retains a bounded number of recent changes per lifetime
    with no per-subscriber queue; a subscriber that falls behind receives gap
    and rebuilds from List. Service-mediated commits are journaled when they
    publish. External additions and deletions are journaled when the provider's
    optional listing capability is polled; changes that cancel out between polls
    are not reported. removed currently reports only external deletions, because
    the service has no delete operation. A provider restart starts a new epoch."""

    def observe(self, cursor: str, max_changes: int, wait_ms: int) -> ChangePage:
        """Empty cursor starts at the current journal end. Cursors are at most 256
        bytes and bind provider epoch and sequence. A cursor from another epoch
        or older than the retained journal returns gap. max_changes is 1..256;
        wait_ms is 0..30000 and waits at the current end for an append, then
        rereads once. Observe authorization is checked on every call and
        rechecked after a wait; each entry is filtered through the read policy
        for its digest. A read decision outage returns unavailable without
        advancing. Bounded waiter exhaustion returns unavailable."""
        raise NotImplementedError

    def list(self, continuation: str, limit: int) -> ListingPage:
        """Empty continuation freezes a new snapshot of the provider's known
        objects and its change cursor. limit is 1..256. Continuations are at
        most 256 bytes and name a retained snapshot; an unknown, expired or
        restarted snapshot returns gap. At most 8 snapshots are retained, each
        for 30 idle seconds; exhaustion returns unavailable. Observe
        authorization and per-object read filtering apply as for Observe."""
        raise NotImplementedError


